1  static inline int read_header(spng_ctx *ctx, int *discard)
     2  {
     3      if(ctx == NULL) return 1;
     4
     5      int ret;
     6      struct spng_chunk chunk = { 0 };
     7
     8      ret = read_and_check_crc(ctx);
     9      if(ret)
    10      {
    11          if(ret == SPNG_CRC_DISCARD)
    12          {
    13              if(discard != NULL) *discard = 1;
    14          }
    15          else return ret;
    16      }
    17
    18      ret = read_data(ctx, 8);
    19      if(ret) return ret;
    20
    21      chunk.offset = ctx->bytes_read - 8;
    22
    23      chunk.length = read_u32(ctx->data);
    24
    25      memcpy(&chunk.type, ctx->data + 4, 4);
    26
    27      if(chunk.length > png_u32max) return SPNG_ECHUNK_SIZE;
    28
    29      ctx->cur_chunk_bytes_left = chunk.length;
    30
    31      ctx->cur_actual_crc = crc32(0, NULL, 0);
    32      ctx->cur_actual_crc = crc32(ctx->cur_actual_crc, chunk.type, 4);
    33
    34      memcpy(&ctx->current_chunk, &chunk, sizeof(struct spng_chunk));
    35
    36      return 0;
    37  }
