    39  /* Read chunk bytes and update crc */
    40  static int read_chunk_bytes(spng_ctx *ctx, uint32_t bytes)
    41  {
    42      if(ctx == NULL) return 1;
    43      if(!bytes) return 0;
    44      if(bytes > ctx->cur_chunk_bytes_left) return 1; /* XXX: more specific error? */
    45
    46      int ret;
    47
    48      ret = read_data(ctx, bytes);
    49      if(ret) return ret;
    50
    51      if(is_critical_chunk(&ctx->current_chunk) &&
    52         ctx->crc_action_critical == SPNG_CRC_USE) goto skip_crc;
    53      else if(ctx->crc_action_ancillary == SPNG_CRC_USE) goto skip_crc;
    54
    55      ctx->cur_actual_crc = crc32(ctx->cur_actual_crc, ctx->data, bytes);
    56
    57  skip_crc:
    58      ctx->cur_chunk_bytes_left -= bytes;
    59
    60      return ret;
    61  }
