    63  static int discard_chunk_bytes(spng_ctx *ctx, uint32_t bytes)
    64  {
    65      if(ctx == NULL) return 1;
    66
    67      int ret;
    68
    69      if(ctx->streaming) /* Do small, consecutive reads */
    70      {
    71          while(bytes)
    72          {
    73              uint32_t len = SPNG_READ_SIZE;
    74
    75              if(len > bytes) len = bytes;
    76
    77              ret = read_chunk_bytes(ctx, len);
    78              if(ret) return ret;
    79
    80              bytes -= len;
    81          }
    82      }
    83      else
    84      {
    85          ret = read_chunk_bytes(ctx, bytes);
    86          if(ret) return ret;
    87      }
    88
    89      return 0;
    90  }
